import boto3
import unittest
from moto import mock_s3
from botocore.exceptions import ClientError
@mock_s3
class ProbeSetup(object):
    def setup(self):
        boto3.client('s3', region_name='us-east-1').create_bucket(Bucket='probe-setup-bucket')
    def test_find(self):
        boto3.client('s3', region_name='us-east-1').head_bucket(Bucket='probe-setup-bucket')
        return 'setup-visible'
@mock_s3
class ProbeSetUp(unittest.TestCase):
    def setUp(self):
        boto3.client('s3', region_name='us-east-1').create_bucket(Bucket='probe-setup-bucket2')
    def test_find(self):
        boto3.client('s3', region_name='us-east-1').head_bucket(Bucket='probe-setup-bucket2')
        return 'setup-visible'
a = ProbeSetup()
a.setup()
ra = a.test_find()
b = ProbeSetUp('test_find')
b.setUp()
rb = b.test_find()
print('moto_sequence', [ra, rb])
assert [ra, rb] == ['setup-visible', 'setup-visible']
